-- 演示角色 catalog 资源授权（nx_permission_grant）。
-- grant_key 格式：domainKey.moduleKey:grantName，与 GET /catalog/permission-catalog 中 resourceKey 一致。
-- grant_key_type：catalog MODULE 级键均为 module（viewGroups / operationGroups 组键）。
--
-- 表字段：grant_id, subject_type, subject_id, grant_key, grant_key_type,
-- constraint_definition, owner_type, owner_id, security_realm, created_at, updated_at
--
-- sys_admin：system（含 plugin）+ operation 全部浏览组与操作组
-- operator：operation 下 role/user/organization 全部浏览组与操作组
-- user：operation 下 role/user/organization 仅 view 浏览组

DELETE FROM nx_permission_grant
WHERE subject_type = 'ROLE'
  AND subject_id IN ('ROL00000000001', 'ROL00000000002', 'ROL00000000003');

